const MODULE_CSS = "/* Module 3: graphite/plum work desk, copper signals, lilac secondary accents. */\n.ml-root{--gold:#edbd91;--bronze:#c99a80;--text:#f5f1f7;--muted:#c3bccc;--line:#b7a2d245;background:radial-gradient(ellipse at 8% 0%,#614a693c,transparent 52%),radial-gradient(ellipse at 100% 100%,#9f603327,transparent 48%),#14121c}\n.ml-head,.ml-body{border-color:#a592ba59;background:linear-gradient(140deg,#302a3b,#1d1a27 60%,#28232e);box-shadow:0 14px 40px #0005,inset 0 1px #f3d8ff12}\n.ml-head{border-radius:10px}.ml-title{color:#f0d1b5}.ml-body{scrollbar-color:#ae93c2 #1d1a27}.ml-progress i.on{background:linear-gradient(90deg,#eebc8b,#c0a4e6);box-shadow:0 0 7px #edbd9120}\n.ml-button.primary{color:#241b22;background:linear-gradient(115deg,#f1cfaa,#d7a17d);border-color:#edbd91}.ml-button.primary:hover:not(:disabled){background:#f5dac0}\n.ml-theory-flow{background:linear-gradient(120deg,#382d42,#262131);border-color:#baa0d65a}.ml-theory-step{background:#302a3d;border-color:#b6a0ce55}.ml-theory-example{background:#d7a17d14}\n.ml-theory-face{background:#302637;border-color:#c09aaa}.ml-theory-face.back{background:#223c34;border-color:#80b99a}.ml-theory-flip.on .ml-theory-flip-inner{transform:rotateY(180deg)}.ml-theory-face.back{transform:rotateY(180deg)}\n.ml-theory-controls button{background:#262031;border-color:var(--line);min-height:44px}.ml-theory-flip,.ml-theory-flip-inner{min-height:114px}.ml-theory-face{overflow-wrap:anywhere}\n.ml-vocab-face{background:#31293e}.ml-vocab-face.back{background:#3c3042}.ml-vocab-card,.ml-vocab-inner{min-height:112px}.ml-token{background:#332b3f;color:#f5f1f7;min-height:44px}\n.ml-card.reveal.open,.ml-bubble.right{background:#b59bce17;border-color:#b59bce77}.ml-bubble{max-width:96%}.ml-option:disabled.good{opacity:1}.ml-option:hover:not(:disabled){background:#c0a4e610}\n.ml-result{background:radial-gradient(ellipse at 20% 50%,#bd876d25,transparent 55%),#241f2e;border-color:#b89a7966}.ml-ring:before{background:#241f2e}.ml-confetti i:nth-child(3n){background:#b8a0df}.ml-confetti i:nth-child(3n+1){background:#e3b68d}.ml-phrase .ml-rate button{min-height:44px}\n.ml-slide{animation-name:m3-slide-in}.ml-theory-enter{animation-name:m3-build}.ml-bubble{animation-name:m3-message}\n@keyframes m3-slide-in{from{opacity:0;transform:perspective(1200px) translateX(18px) rotateY(-3deg)}to{opacity:1;transform:none}}\n@keyframes m3-build{from{opacity:0;transform:translateX(-9px) scale(.98)}to{opacity:1;transform:none}}\n@keyframes m3-message{from{opacity:0;transform:translateY(9px) rotateY(-8deg)}to{opacity:1;transform:none}}\n.m3-scene{position:relative;isolation:isolate;display:grid;grid-template-columns:180px minmax(0,1fr);gap:20px;align-items:center;min-height:204px;padding:18px 24px 48px;border:1px solid #b7a2d24d;border-radius:15px;overflow:hidden;background:linear-gradient(90deg,#b7a2d207 1px,transparent 1px),linear-gradient(#b7a2d207 1px,transparent 1px),radial-gradient(ellipse at 15% 50%,#67476955,transparent 65%),#1a1723;background-size:22px 22px,22px 22px,auto,auto}\n.m3-perspective{width:154px;height:126px;perspective:800px;margin:auto}.m3-dossier{width:146px;height:118px;position:relative;transform-style:preserve-3d;animation:m3-dossier-turn 8s ease-in-out infinite}\n.m3-sheet{position:absolute;inset:0;border:1px solid #bb9cc9;border-radius:8px;background:#352a42;backface-visibility:hidden}.shadow-sheet{transform:translate3d(-12px,10px,-14px);background:#48364f}.middle-sheet{transform:translate3d(-5px,5px,0);background:#5e4660}.front-sheet{transform:translateZ(12px);padding:12px;background:linear-gradient(135deg,#47364d,#292337);box-shadow:0 12px 24px #0005;display:grid;gap:4px;color:#f2cfac}.front-sheet svg{width:76px;height:38px}.m3-doc-label{font-size:8px;letter-spacing:.1em;font-weight:800}.front-sheet strong{font-size:12px}.m3-stamp{position:absolute;bottom:12px;right:7px;border:1px solid #e6b49088;padding:3px;transform:rotate(-8deg);font-size:6px;color:#e6b490}\n@keyframes m3-dossier-turn{0%,100%{transform:rotateY(-22deg) rotateX(9deg) translateY(2px)}50%{transform:rotateY(13deg) rotateX(-4deg) translateY(-4px)}}\n.m3-process{min-width:0;display:grid;gap:12px}.m3-tag{color:#c5addf;font-size:10px;font-weight:800;letter-spacing:.12em}.m3-stages{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.m3-stages>div{display:grid;gap:6px;padding:9px;border:1px solid #b7a2d23d;border-radius:8px;background:#342b4080;animation:m3-stage-signal 6s ease-in-out infinite;animation-delay:calc(var(--step)*2s)}.m3-stages b{font-size:19px;color:#edbd91}.m3-stages span{font-size:10px;font-weight:750;color:#e0d7eb;overflow-wrap:anywhere}.m3-process p{font-size:11px;color:#c3bccc}\n@keyframes m3-stage-signal{0%,30%,100%{border-color:#b7a2d23d;background:#342b4080}10%,20%{border-color:#edbd91;background:#6e4f4c66}}\n.m3-track{position:relative;height:2px;background:#b7a2d23d}.m3-track i{position:absolute;top:-3px;left:0;width:22px;height:8px;border-radius:4px;background:#edbd91;box-shadow:0 0 11px #edbd9177;animation:m3-scan 6s linear infinite}\n@keyframes m3-scan{0%{left:0;opacity:0}10%,90%{opacity:1}100%{left:calc(100% - 22px);opacity:0}}\n.m3-motion{position:absolute;right:10px;bottom:7px;min-height:36px;padding:5px 9px;border:1px solid #b7a2d24d;border-radius:7px;background:#262031;color:#e4c8ad;font-size:10px!important}.m3-scene.paused *{animation-play-state:paused!important}\n.m3-hook{display:grid;gap:12px;border-left:3px solid #c5addf;padding:16px 20px;border-radius:0 12px 12px 0;background:linear-gradient(90deg,#b7a2d212,transparent)}.m3-hook-message{font-size:clamp(22px,3vw,33px);font-weight:750;color:#f0d1b5}\n.m3-document-reader{display:grid;gap:12px}.m3-tabs{display:flex;flex-wrap:wrap;gap:7px}.m3-tabs button{min-height:44px;border:1px solid var(--line);border-radius:8px;padding:8px 12px;background:#211d2c;color:var(--muted);font-size:12px}.m3-tabs button.on{border-color:#edbd91;color:#f5dcc3;background:#59413d66}\n.m3-document{border:1px solid #b7a2d26b;border-radius:13px;background:#211c2b;overflow:hidden;animation:m3-document-open .45s ease both}.m3-document header{display:grid;gap:7px;padding:14px 18px;border-bottom:1px solid var(--line);background:#3a2f44}.m3-document h2{font-size:clamp(17px,2vw,23px);color:#f0d1b5}.m3-document dl{margin:0}.m3-document dl>div{display:grid;grid-template-columns:minmax(120px,.36fr) minmax(0,1fr);gap:16px;padding:10px 18px;border-bottom:1px solid #b7a2d21a}.m3-document dt{color:#c5addf;font-size:12px;font-weight:700}.m3-document dd{margin:0;color:#f5f1f7;font-size:14px;line-height:1.5;white-space:pre-line;overflow-wrap:anywhere}.m3-document-note{padding:12px 18px!important;font-size:12px;color:#c3bccc;background:#d7a17d09}\n@keyframes m3-document-open{from{opacity:0;transform:perspective(1000px) rotateY(-5deg) translateX(10px)}to{opacity:1;transform:none}}\n.m3-source{display:grid;gap:8px;border:1px solid var(--line);border-radius:12px;padding:14px;background:#201a29}.m3-source p{font-size:15px;line-height:1.5}.m3-details{display:grid;gap:12px}.m3-details>.ml-button{justify-self:end}.m3-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.m3-fields label{display:grid;gap:6px;color:#c3bccc;font-size:13px}.m3-fields input{width:100%;min-width:0;min-height:44px;padding:10px;border:1px solid #a18aad;border-radius:8px;background:#181420;color:#f5f1f7;font:inherit}.m3-fields input:focus-visible{outline:2px solid #edbd91;outline-offset:2px}.m3-fields input.good{border-color:#78bc94}.m3-fields input.bad{border-color:#f2a2ac}.m3-fields small{font-size:11px;color:#f2a2ac}.m3-fields small.m3-correct{color:#9cddb5}\n@media(max-width:650px){.m3-scene{grid-template-columns:100px minmax(0,1fr);gap:10px;padding:14px 10px 55px;min-height:190px}.m3-perspective{transform:scale(.65);transform-origin:left center;width:100px;height:100px}.m3-stages{gap:4px}.m3-stages>div{padding:6px 4px}.m3-stages b{font-size:15px}.m3-stages span{font-size:8px}.m3-process{gap:9px}.m3-process p{font-size:10px}.m3-motion{min-height:44px}.m3-hook{padding:12px}.m3-document dl>div{grid-template-columns:1fr;gap:4px;padding:9px 12px}.m3-document header{padding:12px}.m3-document-note{padding:10px 12px!important}.m3-fields{grid-template-columns:1fr}.ml-theory-flip,.ml-theory-flip-inner{min-height:150px}.ml-vocab-card,.ml-vocab-inner{min-height:116px}.ml-foot{flex-wrap:wrap}.ml-note{display:none}.m3-document-reader .ml-note{display:block;font-size:11px}.m3-tabs button{flex:1;font-size:11px}.ml-progress{max-width:42%}.ml-progress i{width:4px}}\n@media(prefers-reduced-motion:reduce){.m3-dossier,.m3-stages>div,.m3-track i{animation:none!important}.m3-dossier{transform:rotateY(-14deg) rotateX(6deg)}.m3-track i{left:50%}.m3-motion{display:none}.m3-document{animation:none}}\n";

function TypeLine({ text, active = true, instant = false, speed = 24 }) {
  const [n, setN] = useState(0);
  useEffect(() => {
    if (!active) { setN(0); return; }
    if (instant || (typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches)) { setN(text.length); return; }
    setN(0);
    let at = 0;
    const timer = setInterval(() => { at += 1; setN(at); if (at >= text.length) clearInterval(timer); }, speed);
    return () => clearInterval(timer);
  }, [text, active, instant, speed]);
  return <span aria-label={text}><span aria-hidden="true">{text.slice(0, n)}</span></span>;
}

function WorkplaceScene() {
  const [paused, setPaused] = useState(false);
  const scene = DATA.scene;
  return <div className={`m3-scene ${paused ? "paused" : ""}`}>
    <div className="m3-perspective" aria-hidden="true"><div className="m3-dossier">
      <div className="m3-sheet shadow-sheet"/><div className="m3-sheet middle-sheet"/>
      <div className="m3-sheet front-sheet"><span className="m3-doc-label">{scene.label}</span><svg viewBox="0 0 120 65" fill="none"><path d="M12 48h96M12 33h68M12 18h42" stroke="currentColor" strokeWidth="4" strokeLinecap="round"/><path d="m86 20 8 8 17-20" stroke="#9bd8b0" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"/></svg><strong>{scene.ref}</strong><span className="m3-stamp">CHECK DETAILS</span></div>
    </div></div>
    <div className="m3-process" aria-hidden="true"><span className="m3-tag">{scene.label}</span><div className="m3-stages">{scene.stages.map((stage, index) => <div key={stage} style={{"--step":index}}><b>{String(index + 1).padStart(2,"0")}</b><span>{stage}</span></div>)}</div><div className="m3-track"><i/></div><p>{scene.detail}</p></div>
    <button className="m3-motion" type="button" aria-pressed={paused} onClick={() => setPaused(value => !value)}>{paused ? "Animatsiyani yoqish" : "Animatsiyani to‘xtatish"}</button>
  </div>;
}

function HookSlide({ slide, onReady }) {
  useEffect(() => { onReady(); }, [onReady]);
  return <><WorkplaceScene/><div className="m3-hook"><span className="m3-tag">WORKPLACE CASE · O‘QUV VAZIYATI</span><p className="m3-hook-message">{slide.lines[0]}</p><p className="ml-lead">{slide.lines[1]}</p><p className="ml-sub">{slide.lines[2]}</p></div></>;
}

function DocumentSlide({ slide, onReady }) {
  const [active, setActive] = useState(0);
  const [reviewed, setReviewed] = useState({});
  const document = slide.documents[active];
  const complete = Object.keys(reviewed).length === slide.documents.length;
  useEffect(() => { if (complete) onReady(); }, [complete, onReady]);
  return <div className="m3-document-reader">
    <p className="ml-sub">{slide.instructions || "Manbani o‘qing. Har hujjatni tekshirgach belgilab chiqing; keyingi mashqlar shu detallarga asoslanadi."}</p>
    <div className="m3-tabs" role="group" aria-label="O‘quv hujjatlari">{slide.documents.map((item, index) => <button type="button" key={item.title} className={active === index ? "on" : ""} aria-pressed={active === index} onClick={() => setActive(index)}>{reviewed[index] ? "✓ " : ""}{item.title}</button>)}</div>
    <article className="m3-document" key={active}><header><span className="m3-tag">SAMPLE DOCUMENT · {active + 1}/{slide.documents.length}</span><h2>{document.title}</h2></header><dl>{document.rows.map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl>{document.note && <p className="m3-document-note">{document.note}</p>}</article>
    <div className="ml-actions"><span className="ml-note" role="status">Ko‘rib chiqildi: {Object.keys(reviewed).length}/{slide.documents.length}</span><button type="button" className="ml-button primary" disabled={!!reviewed[active]} onClick={() => { setReviewed(prev => ({...prev,[active]:true})); if (active < slide.documents.length - 1) setActive(active + 1); }}>{reviewed[active] ? "Tekshirildi ✓" : "Hujjatni ko‘rib chiqdim →"}</button></div>
  </div>;
}

function DetailsSlide({ slide, onReady, onDone }) {
  const [values, setValues] = useState({});
  const [checked, setChecked] = useState(false);
  const [done, setDone] = useState(false);
  const [attempts, setAttempts] = useState(0);
  const normalize = value => String(value || "").trim().toLowerCase().replace(/[.,!?]/g, "").replace(/\s+/g, " ");
  const correct = slide.fields.map(field => [field.answer, ...(field.accept || [])].some(answer => normalize(answer) === normalize(values[field.label])));
  function check(event) {
    event.preventDefault();
    if (done || slide.fields.some(field => !values[field.label]?.trim())) return;
    setChecked(true); setAttempts(value => value + 1);
    if (correct.every(Boolean)) { setDone(true); onDone?.({total:1,firstTry:attempts === 0 ? 1 : 0,attempts:attempts + 1}); onReady(); }
  }
  return <><div className="m3-source"><span className="m3-tag">MANBA · FACT CHECK</span><p>{slide.source}</p></div><div className="m3-details" role="group" aria-label="Ma’lumotlarni tekshirish" onKeyDown={event => { if (event.key === "Enter") check(event); }}>
    <div className="m3-fields">{slide.fields.map((field, index) => <label key={field.label}>{field.label}<input value={values[field.label] || ""} disabled={done} autoComplete="off" spellCheck={false} aria-invalid={checked && !correct[index]} aria-describedby={checked && !correct[index] ? `field-hint-${index}` : undefined} className={checked ? correct[index] ? "good" : "bad" : ""} onChange={event => { setChecked(false); setValues(prev => ({ ...prev, [field.label]: event.target.value })); }}/>{checked && !correct[index] && <small id={`field-hint-${index}`}>{field.hint || "Manbadagi shu detalni qayta tekshiring; raqam va vaqt birligini saqlang."}</small>}{checked && correct[index] && <small className="m3-correct">✓ Mos keldi</small>}</label>)}</div>
    {checked && <p role="status" className={`ml-feedback ${done ? "good" : "bad"}`}>{done ? "✓ Barcha detallar manbaga mos." : "Ayrim detallar mos emas. Tuzatib qayta tekshiring."}</p>}
    <button type="button" className="ml-button primary" onClick={check} disabled={done || slide.fields.some(field => !values[field.label]?.trim())}>Tekshirish →</button>
  </div></>;
}


function TheorySlide({ slide, index, onReady }) {
  const [phase, setPhase] = useState(0);
  const [run, setRun] = useState(0);
  const [skip, setSkip] = useState(false);
  const [flipped, setFlipped] = useState(false);
  const reduced = typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
  const visible = skip || reduced ? 8 : phase;
  useEffect(() => {
    if (skip || reduced) return;
    const timers = [];
    let delay = slide.explanation.length * 18 + 250;
    for (let step = 1; step <= 3; step++) { timers.push(setTimeout(() => setPhase(step), delay)); delay += 470; }
    for (let point = 0; point < 2; point++) { timers.push(setTimeout(() => setPhase(point + 4), delay)); delay += slide.points[point].length * 14 + 180; }
    timers.push(setTimeout(() => setPhase(6), delay)); delay += slide.example.length * 18 + 200;
    timers.push(setTimeout(() => setPhase(7), delay)); delay += slide.translation.length * 18 + 220;
    timers.push(setTimeout(() => setPhase(8), delay));
    return () => timers.forEach(clearTimeout);
  }, [slide, run, skip, reduced]);
  const show = at => visible >= at ? "ml-theory-enter" : "ml-theory-hidden";
  return <div className="ml-theory">
    <div className="ml-theory-top"><span className="ml-kick">ASOSIY QOIDA · {index + 1}/{DATA.theoryCount}</span><div className="ml-theory-controls"><button type="button" onClick={() => { setPhase(0); setSkip(false); setFlipped(false); setRun(value => value + 1); }}>Qayta</button><button type="button" disabled={visible === 8} onClick={() => setSkip(true)}>Hammasi</button></div></div>
    <p className="ml-theory-rule"><TypeLine key={`rule-${run}`} text={slide.explanation} instant={skip} speed={18} /></p>
    <div className="ml-theory-flow" aria-label={visible >= 3 ? slide.steps.map(step => step[1]).join(" → ") : undefined}>{slide.steps.map(([label, value], at) => <React.Fragment key={at}>{at > 0 && <span className={`ml-theory-arrow ${show(at + 1)}`} aria-hidden={visible < at + 1}>→</span>}<div className={`ml-theory-step ${show(at + 1)}`} aria-hidden={visible < at + 1}><small>{label}</small><strong>{value}</strong></div></React.Fragment>)}</div>
    <div className="ml-theory-points">{slide.points.map((point, at) => <p key={at} className={show(at + 4)} aria-hidden={visible < at + 4}><TypeLine key={`point-${run}-${at}`} text={point} active={visible >= at + 4} instant={skip} speed={14} /></p>)}</div>
    <div className={`ml-theory-example ${show(6)}`} aria-hidden={visible < 6}><strong><TypeLine key={`example-${run}`} text={slide.example} active={visible >= 6} instant={skip} speed={18} /></strong><span><TypeLine key={`translation-${run}`} text={slide.translation} active={visible >= 7} instant={skip} speed={18} /></span></div>
    <button type="button" className={`ml-theory-flip ${show(8)} ${flipped ? "on" : ""}`} disabled={visible < 8} aria-hidden={visible < 8} aria-pressed={flipped} onClick={() => { setFlipped(true); onReady(); }}><span className="ml-theory-flip-inner"><span className="ml-theory-face"><small>XATO · TUZATISH UCHUN BOSING</small><strong>{slide.wrong}</strong></span><span className="ml-theory-face back"><small>TO‘G‘RI ✓</small><strong>{slide.right}</strong><em>{slide.why}</em></span></span></button>
  </div>;
}

function Card({ text, index, opened, onOpen }) {
  const divider = text.indexOf(":");
  const label = divider > 0 && divider < 42 ? text.slice(0, divider + 1) : "";
  const rest = label ? text.slice(divider + 1).trim() : text;
  return <button type="button" className={`ml-card reveal ${opened ? "open" : ""}`} style={{ "--delay": `${index * .11}s` }} aria-expanded={opened} onClick={onOpen}><div className="hint">{label || `QOIDA ${index + 1}`}</div><p className="hidden-copy">{opened ? <TypeLine text={rest} /> : "Ko‘rish uchun bosing ↗"}</p></button>;
}

function RevealSlide({ slide, onReady }) {
  const [seen, setSeen] = useState({});
  const cards = slide.cards || [];
  useEffect(() => { if (cards.length === 0 || Object.keys(seen).length >= cards.length) onReady(); }, [seen, cards.length, onReady]);
  return <><div className="ml-card-grid"><div className="ml-card"><div className="hint">NAZARIYA · {slide.number}</div><p className="ml-lead">{slide.heading}</p><small>Kartalarni ketma-ket ochib qoidani o‘rganing.</small></div>{cards.map((line, index) => <Card key={index} text={line} index={index} opened={!!seen[index]} onOpen={() => setSeen(prev => ({ ...prev, [index]: true }))} />)}</div></>;
}

function ChatSlide({ slide, onReady }) {
  const [translation, setTranslation] = useState(false);
  useEffect(() => { const timer = setTimeout(onReady, Math.min(1800, (slide.chat?.length || 1) * 200)); return () => clearTimeout(timer); }, [onReady, slide]);
  return <><div className="ml-chat">{slide.chat.map(([who, line], index) => <div className={`ml-bubble ${index % 2 ? "right" : ""}`} style={{ "--delay": `${index * .14}s` }} key={index}><small>{who}</small><p>{line}</p></div>)}</div>{slide.translation && <><button type="button" className="ml-button" style={{ justifySelf: "start" }} onClick={() => setTranslation(!translation)} aria-expanded={translation}>Tarjima {translation ? "−" : "+"}</button>{translation && <p className="ml-sub">{slide.translation}</p>}</>}</>;
}

function VocabSlide({ slide, onReady }) {
  const [seen, setSeen] = useState({});
  useEffect(() => { if (Object.keys(seen).length >= slide.rows.length) onReady(); }, [seen, slide.rows.length, onReady]);
  return <><p className="ml-sub">Kartalarni bosing: so‘zning ma’nosi va logistikadagi misolini ko‘ring.</p><div className="ml-card-grid cols3">{slide.rows.map(([word, meaning, example], index) => <button key={word} type="button" className={`ml-vocab-card ${seen[index] ? "open" : ""}`} style={{ animationDelay: `${index * .08}s` }} onClick={() => setSeen(prev => ({ ...prev, [index]: true }))} aria-label={`${word}: ${meaning}`} aria-pressed={!!seen[index]}><span className="ml-vocab-inner"><span className="ml-vocab-face"><small className="hint">LOGISTICS · {index + 1}</small><strong>{word}</strong><small>Bosing ↗</small></span><span className="ml-vocab-face back"><strong>{meaning}</strong><small>{example}</small></span></span></button>)}</div></>;
}

function shuffled(question) {
  const items = question.options.map((text, id) => ({ text, id }));
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  return items;
}

function ChoiceSlide({ slide, onDone, final = false }) {
  const questions = slide.questions || [];
  const [index, setIndex] = useState(0);
  const [selection, setSelection] = useState(null);
  const [completed, setCompleted] = useState(false);
  const [order] = useState(() => questions.map(shuffled));
  const first = useRef({});
  const question = questions[index];
  const correct = selection === question?.answer;
  const choose = (id) => {
    if (selection === question.answer || (final && selection !== null)) return;
    if (first.current[index] === undefined) first.current[index] = id === question.answer;
    setSelection(id);
  };
  const next = () => {
    if (index + 1 < questions.length) { setIndex(index + 1); setSelection(null); return; }
    const score = Object.values(first.current).filter(Boolean).length;
    setCompleted(true);
    onDone({ firstTry: score, total: questions.length });
  };
  if (!question) return <p className="ml-feedback bad">Savol topilmadi.</p>;
  if (completed) return <div className="ml-feedback good">{questions.length} ta savol tugadi. Birinchi urinishda {Object.values(first.current).filter(Boolean).length} ta to‘g‘ri.</div>;
  return <><span className="ml-kick">SAVOL {index + 1} / {questions.length}</span>{slide.kind === "mission" && <WorkplaceScene />}{slide.kind === "mission" && slide.intro?.filter(line => !line.startsWith("Feedback:")).map((line, i) => <p className="ml-sub" key={i}>{line}</p>)}<p className="ml-lead">{question.stem || "To‘g‘ri javobni tanlang."}</p><div className="ml-options">{order[index].map((option, optionIndex) => <button type="button" key={option.id} className={`ml-option ${selection === option.id ? (correct ? "good" : "bad") : ""}`} disabled={correct || (final && selection !== null)} onClick={() => choose(option.id)}><i>{String.fromCharCode(65 + optionIndex)}</i><span>{option.text}</span></button>)}</div>{selection !== null && <p className={`ml-feedback ${correct ? "good" : "bad"}`} aria-live="polite">{correct ? `✓ To‘g‘ri. ${question.why || "Javob mos keldi."}` : final ? "Bu javob noto‘g‘ri. Keyingi savolga o‘ting." : `“${question.options[selection]}” variantini manba bilan solishtiring. ${question.hint || question.why || "Fakt, vaqt va shart mosligini tekshiring."}`}</p>}<button type="button" className="ml-button primary" style={{ justifySelf: "end" }} disabled={selection === null || (!correct && !final)} onClick={next}>{index + 1 < questions.length ? "Keyingi savol" : "Natijani ko‘rish"} →</button></>;
}

function BuildSlide({ slide, onDone }) {
  const [index, setIndex] = useState(0);
  const [selected, setSelected] = useState([]);
  const [checked, setChecked] = useState(false);
  const [first, setFirst] = useState(0);
  const [attempted, setAttempted] = useState({});
  const [completed, setCompleted] = useState(false);
  const [tokenOrders] = useState(() => slide.builds.map(item => shuffled({ options: item.parts })));
  const build = slide.builds[index];
  const normalize = value => value.replace(/,/g, "").replace(/\s+([?.!])/g, "$1").replace(/[?.!]$/, "").replace(/\s+/g, " ").trim().toLowerCase();
  const assembled = selected.map(i => build.parts[i]).join(" ");
  const isRight = normalize(assembled) === normalize(build.answer);
  const check = () => {
    setChecked(true);
    if (!attempted[index]) { setAttempted(prev => ({ ...prev, [index]: true })); if (isRight) setFirst(prev => prev + 1); }
  };
  const advance = () => {
    if (index + 1 < slide.builds.length) { setIndex(index + 1); setSelected([]); setChecked(false); return; }
    setCompleted(true); onDone({ firstTry: first, total: slide.builds.length });
  };
  if (completed) return <p className="ml-feedback good">3 ta gap tuzildi. Birinchi urinishda {first} ta to‘g‘ri.</p>;
  return <><span className="ml-kick">GAP {index + 1} / {slide.builds.length}</span><p className="ml-sub">So‘zlarni to‘g‘ri tartibda birlashtiring.</p><div className="ml-token-wrap">{selected.length ? selected.map((partIndex, at) => <button type="button" key={`${partIndex}-${at}`} className="ml-token" onClick={() => { setSelected(prev => prev.filter((_, i) => i !== at)); setChecked(false); }}>{build.parts[partIndex]}</button>) : <span className="ml-dim">Gap shu yerda yig‘iladi...</span>}</div><div className="ml-token-wrap">{tokenOrders[index].map(({ text: part, id: partIndex }) => <button type="button" key={partIndex} className="ml-token" disabled={selected.includes(partIndex)} onClick={() => { setSelected(prev => [...prev, partIndex]); setChecked(false); }}>{part}</button>)}</div>{checked && <p className={`ml-feedback ${isRight ? "good" : "bad"}`} aria-live="polite">{isRight ? "✓ To‘g‘ri gap tuzildi." : "So‘z tartibini qayta ko‘ring. Fe’lning joyiga e’tibor bering."}</p>}<div className="ml-actions"><button type="button" className="ml-button" onClick={() => { setSelected([]); setChecked(false); }}>Qayta boshlash</button>{checked && isRight ? <button type="button" className="ml-button primary" onClick={advance}>Keyingi gap →</button> : <button type="button" className="ml-button primary" disabled={selected.length !== build.parts.length} onClick={check}>Tekshirish →</button>}</div></>;
}

function SummarySlide({ slide, rate, setRate }) {
  return <><p className="ml-sub">Iboralarni ovoz chiqarib o‘qing va o‘zingizni baholang. Ovoz yozilmaydi.</p><div className="ml-summary-grid">{slide.phrases.map((phrase, index) => <div className="ml-phrase" key={index} style={{ "--delay": `${index * .1}s` }}><p>{phrase}</p><div className="ml-rate">{[["hard", "Qiyin"], ["ok", "O‘rtacha"], ["easy", "Oson"]].map(([value, label]) => <button type="button" key={value} className={rate[index] === value ? "on" : ""} onClick={() => setRate(prev => ({ ...prev, [index]: value }))}>{label}</button>)}</div></div>)}</div>{slide.extras.map((extra, index) => <p className="ml-sub" key={index}>{extra}</p>)}</>;
}

function Result({ result }) {
  const passed = result.firstTry / result.total >= DATA.threshold;
  return <div className="ml-result"><div className="ml-result-art">{passed && <div className="ml-confetti" aria-hidden="true">{Array.from({ length: 16 }, (_, index) => <i key={index} style={{ "--angle": `${index * 22.5}deg`, "--delay": `${index * -.22}s` }} />)}</div>}<div className="ml-ring" style={{ "--score": `${result.firstTry / result.total * 100}%` }} role="img" aria-label={`${result.firstTry} / ${result.total}`}><span><small>NATIJA</small><strong>{result.firstTry}/{result.total}</strong></span></div></div><div className="ml-result-copy"><svg viewBox="0 0 72 64" fill="none" aria-hidden="true"><path d="M5 9c12-4 23-3 31 4 8-7 19-8 31-4v44c-12-4-23-3-31 4-8-7-19-8-31-4V9Z" fill="currentColor" opacity=".8"/><path d="M36 13v44" stroke="#30251a" strokeWidth="3"/><circle cx="57" cy="11" r="11" fill="#e8c98f"/><path d="m52 11 3 3 6-7" stroke="#20252a" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/></svg><h2>{passed ? "Nazariy dars yakunlandi" : "Nazariyani takrorlang"}</h2><p>{passed ? DATA.code === "M3L08" ? "Module 3 nazariyasi yakunlandi. Ish hujjatlarini o‘qish, noaniqlikni so‘rash va tekshirilgan update yozishni mashq qildingiz." : "Tabriklaymiz! Endi bilimni amaliy mashg‘ulotda mustahkamlang." : `O‘tish uchun kamida ${Math.ceil(result.total * DATA.threshold)} ta to‘g‘ri javob kerak. Qoidalarni qayta ko‘rib, tezkor testni takrorlang.`}</p><b className="ml-strong">{passed ? "Ajoyib, o‘tdingiz!" : "Yana urinib ko‘ring"}</b></div></div>;
}

export default function Lesson({ onFinished, onProgress }) {
  const [current, setCurrent] = useState(0);
  const [ready, setReady] = useState({});
  const [results, setResults] = useState({});
  const [rate, setRate] = useState({});
  const [finished, setFinished] = useState(false);
  const started = useRef(Date.now());
  const done = useRef(false);
  const slides = DATA.slides;
  const slide = slides[current];
  const bodyRef = useRef(null);
  useEffect(() => { if (bodyRef.current) bodyRef.current.scrollTop = 0; }, [current]);
  const rapidIndex = slides.findIndex(item => item.kind === "quiz" && /rapid test|checkpoint 3/i.test(item.heading));
  const rapid = results[rapidIndex];
  const resultScreen = current === rapidIndex && !!rapid;
  useEffect(() => { onProgress?.({ current: current + 1, total: slides.length }); }, [current, onProgress, slides.length]);
  const markReady = useCallback(() => setReady(prev => prev[current] ? prev : ({ ...prev, [current]: true })), [current]);
  const record = value => { setResults(prev => ({ ...prev, [current]: value })); markReady(); };
  const finish = () => {
    if (done.current || !rapid || rapid.firstTry / rapid.total < DATA.threshold) return;
    done.current = true; setFinished(true);
    const score = rapid || { firstTry: 0, total: DATA.code === "M3L08" ? 8 : 4 };
    const all = Object.values(results);
    onFinished?.({ lessonId: `${DATA.code}-learn`, lessonTitle: DATA.title, durationSec: Math.max(0, Math.round((Date.now() - started.current) / 1000)), totalQuestions: score.total, correctAnswers: score.firstTry, scorePercent: Math.round(score.firstTry / score.total * 100), passed: score.firstTry / score.total >= DATA.threshold, firstTryStats: { total: all.reduce((sum, item) => sum + item.total, 0), firstTryCorrect: all.reduce((sum, item) => sum + item.firstTry, 0) }, skillTags: DATA.skillTags, answers: Object.entries(results).map(([index, value]) => ({ slide: Number(index) + 1, ...value })), profile: { aloud: rate } });
  };
  let content;
  const props = { slide, onReady: markReady, onDone: record };
  if (slide.kind === "hook") content = <HookSlide key={current} {...props} />;
  else if (slide.kind === "document") content = <DocumentSlide key={current} {...props} />;
  else if (slide.kind === "details") content = <DetailsSlide key={current} {...props} />;
  else if (slide.kind === "theory") content = <TheorySlide key={current} {...props} index={current - 1} />;
  else if (slide.kind === "read") content = <ChatSlide key={current} {...props} />;
  else if (slide.kind === "vocab") content = <VocabSlide key={current} {...props} />;
  else if (slide.kind === "mission" || slide.kind === "quiz") content = resultScreen ? <Result result={rapid} /> : <ChoiceSlide key={current} {...props} final={current === rapidIndex} />;
  else if (slide.kind === "build") content = <BuildSlide key={current} {...props} />;
  else if (slide.kind === "summary") content = <SummarySlide key={current} {...props} rate={rate} setRate={setRate} />;
  else content = <RevealSlide key={current} {...props} />;
  const failedTest = resultScreen && rapid.firstTry / rapid.total < DATA.threshold;
  const canContinue = !failedTest && (!!ready[current] || slide.kind === "summary");
  return <main className="ml-root"><style>{CSS + MODULE_CSS}</style><header className="ml-head"><span className="ml-eyebrow">M03 / WORKPLACE · {DATA.code} · {current + 1}/{slides.length}</span><span className="ml-progress" aria-hidden="true">{slides.map((_, index) => <i key={index} className={index <= current ? "on" : ""} />)}</span></header><section className="ml-body" ref={bodyRef}><div className="ml-slide" key={current}><div><div className="ml-kick">{slide.kind === "hook" ? "HOOK" : slide.kind === "document" ? "HUJJAT TAHLILI" : slide.kind === "details" ? "AMALDA QO‘LLASH" : slide.kind === "theory" ? `ASOSIY QOIDA · ${current}/${DATA.theoryCount}` : slide.kind === "quiz" ? "TEKSHIRUV" : slide.kind === "vocab" ? "SO‘ZLAR" : "NAZARIYA"} · {DATA.code}</div><h1 className="ml-title"><TypeLine text={slide.heading} /></h1></div>{current === 0 && <p className="ml-sub">{DATA.goal}</p>}{content}</div></section><footer className="ml-foot"><button type="button" className="ml-button" disabled={current === 0} onClick={() => setCurrent(current - 1)}>← Orqaga</button>{!canContinue && <span className="ml-note">Davom etish uchun vazifani bajaring</span>}{failedTest && <button type="button" className="ml-button primary" onClick={() => { setResults(prev => { const next = { ...prev }; delete next[current]; return next; }); setReady(prev => ({ ...prev, [current]: false })); }}>Testni qayta ishlash →</button>}{finished ? <span className="ml-feedback good">Natija saqlandi ✓</span> : current < slides.length - 1 ? <button type="button" className="ml-button primary" disabled={!canContinue} onClick={() => setCurrent(current + 1)}>{resultScreen ? "Davom etish" : "Keyingi slayd"} →</button> : <button type="button" className="ml-button primary" onClick={finish}>Darsni yakunlash →</button>}</footer></main>;
}
